long long number_input;
long long power_levels[20], degree_levels[20];

long long compute_min(long long current_value, int level) {
    current_value = abs(current_value);
    if (current_value % power_levels[level] == 0)
        return (current_value / power_levels[level]) * level;
    long long q = current_value / power_levels[level];
    long long candidate1 = q * level + compute_min(current_value - q * power_levels[level], level - 1);
    long long candidate2 = (q + 1) * level + compute_min((q + 1) * power_levels[level] - current_value, level - 1);
    return min(candidate1, candidate2);
}

void main_process() {
    power_levels[1] = 1;
    for (int i = 0; i < 17; ++i)
        power_levels[i + 2] = power_levels[i + 1] * 10 + 1;
    cin >> number_input;
    cout << compute_min(number_input, 18) << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    main_process();
    return 0;
